### Ready‑to‑paste code (Next.js 13)

Create a new file:

`app/api/products/route.ts`

```ts
import { createClient } from '@supabase/supabase-js';
import type { NextRequest } from 'next/server';

// 1️⃣ Create a Supabase client that uses the service role key (not exposed to the browser)
const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL as string,
  process.env.SUPABASE_SERVICE_ROLE_KEY as string, // keep it in .env
  { db: { schema: 'public' } }
);

// 2️⃣ Simple in‑memory rate limit (10 req/min per IP)
const rateLimit = new Map<string, { count: number; reset: number }>();
const MAX_REQ = 10;
const WINDOW_MS = 60_000; // 1 minute

export async function GET(request: NextRequest) {
  // 3️⃣ Rate‑limit logic
  const ip = request.headers.get('x-forwarded-for') || request.ip || 'unknown';
  const now = Date.now();
  const record = rateLimit.get(ip) || { count: 0, reset: now + WINDOW_MS };
  if (now > record.reset) {
    record.count = 0;
    record.reset = now + WINDOW_MS;
  }
  if (record.count >= MAX_REQ) {
    return new Response('Rate limit exceeded', { status: 429 });
  }
  record.count += 1;
  rateLimit.set(ip, record);

  // 4️⃣ Query only public products
  const { data: products, error } = await supabase
    .from('products')
    .select('*')
    .eq('is_public', true);

  if (error) {
    console.error('Supabase error:', error);
    return new Response('Internal error', { status: 500 });
  }

  // 5️⃣ Return JSON
  return new Response(JSON.stringify(products), {
    headers: { 'content-type': 'application/json' },
  });
}
```

**What you need to add/ensure**

1. **`.env`**  
   ```env
   NEXT_PUBLIC_SUPABASE_URL=https://your-project.supabase.co
   SUPABASE_SERVICE_ROLE_KEY=your‑service‑role‑key
   ```  
   *_Do not commit this file to a public repo.* Add `.env` to `.gitignore` (or use your platform’s secrets UI).

2. **Database changes**  
   - Add a boolean column `is_public` to `products` (default `false`).  
   - For existing products you want public, set `is_public = true`.  

   ```sql
   alter table products add column is_public boolean default false;
   update products set is_public = true where <your‑condition>;
   ```

3. **Deploy**  
   Just push your repo (Next.js automatically serves the API route).  
   If you’re using Vercel, the environment variables are set in the project settings.

